import java.util.*;class Solution{Map<String,List<String>>pre=new HashMap<>();List<List<String>>o=new ArrayList<>();void dfs(String w,String b,List<String>p){p.add(w);if(w.equals(b)){List<String>v=new ArrayList<>(p);Collections.reverse(v);o.add(v);}else for(String x:pre.getOrDefault(w,List.of()))dfs(x,b,p);p.remove(p.size()-1);}public List<List<String>> findLadders(String b,String e,List<String>wl){Set<String>dct=new HashSet<>(wl);if(!dct.contains(e))return o;Queue<String>q=new ArrayDeque<>();Map<String,Integer>d=new HashMap<>();q.add(b);d.put(b,0);while(!q.isEmpty()){String w=q.remove();int nd=d.get(w)+1;char[]a=w.toCharArray();for(int i=0;i<a.length;i++){char old=a[i];for(char c='a';c<='z';c++){a[i]=c;String x=new String(a);if(dct.contains(x)){if(!d.containsKey(x)){d.put(x,nd);q.add(x);}if(d.get(x)==nd)pre.computeIfAbsent(x,k->new ArrayList<>()).add(w);}}a[i]=old;}}if(d.containsKey(e))dfs(e,b,new ArrayList<>());return o;}}
